import { rathenaDb } from "../parsers/rathenaParser";
import { prisma } from "../db/prisma";
export async function importRathenaMobs() {
    for (const mob of rathenaDb.getAllMobs()) {
        await prisma.mob.upsert({
            where: { id: mob.id },
            create: {
                id: mob.id,
                aegisName: mob.aegisName,
                name: mob.name,
                level: mob.level,
                hp: mob.hp,
                sp: mob.sp,
                baseExp: mob.baseExp,
                jobExp: mob.jobExp,
                attack: mob.attack,
                attack2: mob.attack2,
                defense: mob.defense,
                magicDefense: mob.magicDefense,
                str: mob.str,
                agi: mob.agi,
                vit: mob.vit,
                int: mob.int,
                dex: mob.dex,
                luk: mob.luk,
                attackRange: mob.attackRange,
                skillRange: mob.skillRange,
                chaseRange: mob.chaseRange,
                size: mob.size,
                race: mob.race,
                element: mob.element,
                elementLevel: mob.elementLevel,
                walkSpeed: mob.walkSpeed,
                attackDelay: mob.attackDelay,
                attackMotion: mob.attackMotion,
                damageMotion: mob.damageMotion,
                ai: mob.ai,
            },
            update: {
                id: mob.id,
                aegisName: mob.aegisName,
                name: mob.name,
                level: mob.level,
                hp: mob.hp,
                sp: mob.sp,
                baseExp: mob.baseExp,
                jobExp: mob.jobExp,
                attack: mob.attack,
                attack2: mob.attack2,
                defense: mob.defense,
                magicDefense: mob.magicDefense,
                str: mob.str,
                agi: mob.agi,
                vit: mob.vit,
                int: mob.int,
                dex: mob.dex,
                luk: mob.luk,
                attackRange: mob.attackRange,
                skillRange: mob.skillRange,
                chaseRange: mob.chaseRange,
                size: mob.size,
                race: mob.race,
                element: mob.element,
                elementLevel: mob.elementLevel,
                walkSpeed: mob.walkSpeed,
                attackDelay: mob.attackDelay,
                attackMotion: mob.attackMotion,
                damageMotion: mob.damageMotion,
                ai: mob.ai,
            },
        });
    }
    return rathenaDb.getMobCount();
}
